1	/**
2	 * upload-handlers.ts
3	 *
4	 * R2-native file upload endpoints.
5	 *
6	 * These are registered on the Hono app BEFORE the generic `/api/*` catch-all
7	 * so they take priority. They write directly to R2 rather than going through
8	 * the multer-based Express middleware (which is shimmed as a no-op in CF).
9	 */
10	
11	import type { Hono } from "hono";
12	import { buildRequestResources } from "./route-registry.js";
13	import { resolveActorFromRequest } from "../auth/resolve-actor.js";
14	import { HttpError } from "../../../../server/src/errors.js";
15	import type { Env } from "./env.js";
16	import { resolveDeploymentMode } from "./env.js";
17	
18	export function registerUploadHandlers(app: Hono<{ Bindings: Env }>): void {
19	  // PUT /api/assets/:assetId/upload
20	  // Streams the request body directly into R2 under assets/<companyId>/<assetId>.
21	  app.put("/api/assets/:assetId/upload", async (c) => {
22	    const { assets } = await import("../../../db/src/schema/index.js");
23	    const { eq } = await import("drizzle-orm");
24	    const { forbidden, notFound, badRequest } = await import("../../../../server/src/errors.js");
25	
26	    const env = c.env;
27	    const { db } = buildRequestResources(env);
28	    const actor = await resolveActorFromRequest(c.req.raw, db, { deploymentMode: resolveDeploymentMode(env) });
29	
30	    try {
31	      const assetId = c.req.param("assetId");
32	      if (!assetId) return c.json({ error: "Missing assetId" }, 400);
33	
34	      const assetRow = await db.select().from(assets).where(eq(assets.id, assetId)).then((rows) => rows[0] ?? null);
35	      if (!assetRow) throw notFound("Asset not found");
36	
37	      if (!actor) throw forbidden("Authentication required");
38	      if (actor.type === "board" && !actor.isInstanceAdmin && !actor.companyIds?.includes(assetRow.companyId)) {
39	        throw forbidden("No access to this company");
40	      }
41	      if (actor.type === "agent" && actor.companyId !== assetRow.companyId) {
42	        throw forbidden("No access to this company");
43	      }
44	
45	      const body = c.req.raw.body;
46	      if (!body) throw badRequest("Empty request body");
47	      const key = `assets/${assetRow.companyId}/${assetId}`;
48	      await env.PAPERCLIP_STORAGE.put(key, body, {
49	        httpMetadata: { contentType: c.req.header("content-type") ?? "application/octet-stream" },
50	      });
51	      return c.json({ ok: true, key });
52	    } catch (err) {
53	      if (err instanceof HttpError) return c.json({ error: err.message }, err.status as 400 | 403 | 404);
54	      console.error("[CF Worker] PUT /api/assets/:assetId/upload", err);
55	      return c.json({ error: "Internal Server Error" }, 500);
56	    }
57	  });
58	
59	  // POST /api/issues/:issueId/attachments/upload
60	  // Streams the request body into R2 under issues/<companyId>/<issueId>/attachments/<filename>.
61	  app.post("/api/issues/:issueId/attachments/upload", async (c) => {
62	    const { issues } = await import("../../../db/src/schema/index.js");
63	    const { eq } = await import("drizzle-orm");
64	    const { forbidden, notFound, badRequest } = await import("../../../../server/src/errors.js");
65	
66	    const env = c.env;
67	    const { db } = buildRequestResources(env);
68	    const actor = await resolveActorFromRequest(c.req.raw, db, { deploymentMode: resolveDeploymentMode(env) });
69	
70	    try {
71	      const issueId = c.req.param("issueId");
72	      if (!issueId) return c.json({ error: "Missing issueId" }, 400);
73	
74	      const issueRow = await db
75	        .select({ id: issues.id, companyId: issues.companyId })
76	        .from(issues)
77	        .where(eq(issues.id, issueId))
78	        .then((rows) => rows[0] ?? null);
79	      if (!issueRow) throw notFound("Issue not found");
80	
81	      if (!actor) throw forbidden("Authentication required");
82	      if (actor.type === "board" && !actor.isInstanceAdmin && !actor.companyIds?.includes(issueRow.companyId)) {
83	        throw forbidden("No access to this company");
84	      }
85	      if (actor.type === "agent" && actor.companyId !== issueRow.companyId) {
86	        throw forbidden("No access to this company");
87	      }
88	
89	      const body = c.req.raw.body;
90	      if (!body) throw badRequest("Empty request body");
91	      const filename = (c.req.header("x-filename") ?? "attachment").replace(/[^a-zA-Z0-9._-]/g, "_");
92	      const key = `issues/${issueRow.companyId}/${issueId}/attachments/${filename}`;
93	      await env.PAPERCLIP_STORAGE.put(key, body, {
94	        httpMetadata: { contentType: c.req.header("content-type") ?? "application/octet-stream" },
95	      });
96	      return c.json({ ok: true, key, filename });
97	    } catch (err) {
98	      if (err instanceof HttpError) return c.json({ error: err.message }, err.status as 400 | 403 | 404);
99	      console.error("[CF Worker] POST /api/issues/:issueId/attachments/upload", err);
100	      return c.json({ error: "Internal Server Error" }, 500);
101	    }
102	  });
103	}
